assignment.solution:
class NotFoundError extends Error {
  constructor(message) {
    super(message);
    this.name = "NotFoundError";
  }
}

function findUser(id) {
  if (id !== 1) {
    throw new NotFoundError(`User ${id} not found`);
  }
  return { id, name: "Ana" };
}

try {
  findUser(5);
} catch (error) {
  console.log(error.name, error.message); // "NotFoundError" "User 5 not found"
}

